import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import {
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;
export const durationInFrames = 180;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeTint: BRAND.colors.orangeTint,
};

// ---------- Check icon ----------
const CheckIcon: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    style={{ flexShrink: 0, opacity: progress }}
  >
    <path
      d="M5 12.5 L10 17.5 L19 7"
      stroke={COLORS.orange}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={28}
      strokeDashoffset={interpolate(progress, [0, 1], [28, 0])}
    />
  </svg>
);

// ---------- Pricing Card Scene ----------
const FEATURES: { label: string }[] = [
  { label: "$0.2 per compute unit" },
  { label: "Community support" },
];

const PricingCardScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Card
  const cardIn = springIn(frame, vfps, TIMING.entrance + 14, "LIQUID");

  // Inner card elements
  const planIn = springIn(frame, vfps, TIMING.entrance + 22, "GENTLE");
  const priceIn = springIn(frame, vfps, TIMING.entrance + 28, "SNAPPY");
  const taglineIn = springIn(frame, vfps, TIMING.entrance + 38, "GENTLE");

  const priceScale = interpolate(priceIn, [0, 1], [0.85, 1]);

  // CTA + footer
  const ctaIn = springIn(frame, vfps, TIMING.entrance + 66, "LIQUID");
  const footerIn = springIn(frame, vfps, TIMING.entrance + 78, "GENTLE");

  // Ambient drift on the card so it doesn't freeze
  const cardDriftY = ambientDrift(frame, 2.5, 120, "pricing-card-y");
  const cardDriftX = ambientDrift(frame, 1.2, 160, "pricing-card-x");

  // Sizing
  const cardWidth = base * 0.34;
  const cardPadding = base * 0.028;
  const cardRadius = base * 0.018;

  const planSize = base * 0.034;
  const priceSize = base * 0.115;
  const taglineSize = base * 0.018;
  const featureSize = base * 0.018;
  const ctaSize = base * 0.022;
  const footerSize = base * 0.014;
  const iconSize = base * 0.022;

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif" }}>
      {/* Lower third: floating pricing card */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "68%",
          transform: `translate(calc(-50% + ${cardDriftX}px), calc(-50% + ${cardDriftY}px))`,
          width: cardWidth,
          fontFamily: "Inter, sans-serif",
        }}
      >
        <div
          style={{
            position: "relative",
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: cardRadius,
            padding: cardPadding,
            opacity: cardIn,
            transform: `translateY(${interpolate(
              cardIn,
              [0, 1],
              [28, 0],
            )}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
            filter: `blur(${interpolate(cardIn, [0, 1], [6, 0])}px)`,
            fontFamily: "Inter, sans-serif",
            display: "flex",
            flexDirection: "column",
          }}
        >
          {/* Plan name */}
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: planSize,
              fontWeight: 700,
              color: COLORS.text,
              letterSpacing: "-0.02em",
              lineHeight: 1,
              opacity: planIn,
              transform: `translateY(${interpolate(
                planIn,
                [0, 1],
                [10, 0],
              )}px)`,
            }}
          >
            Free
          </div>

          {/* Price */}
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontSize: priceSize,
              fontWeight: 800,
              color: COLORS.text,
              letterSpacing: "-0.045em",
              lineHeight: 1,
              marginTop: base * 0.008,
              opacity: priceIn,
              transform: `translateY(${interpolate(
                priceIn,
                [0, 1],
                [14, 0],
              )}px) scale(${priceScale})`,
              transformOrigin: "left center",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            $0
          </div>

          {/* Tagline */}
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: taglineSize,
              fontWeight: 500,
              color: COLORS.textMuted,
              letterSpacing: "-0.005em",
              lineHeight: 1.4,
              marginTop: base * 0.018,
              maxWidth: "92%",
              opacity: taglineIn,
              transform: `translateY(${interpolate(
                taglineIn,
                [0, 1],
                [10, 0],
              )}px)`,
            }}
          >
            $5 to spend in Apify Store or on your own Actors
          </div>

          {/* Feature list */}
          <div
            style={{
              marginTop: base * 0.026,
              display: "flex",
              flexDirection: "column",
              gap: base * 0.014,
              fontFamily: "Inter, sans-serif",
            }}
          >
            {FEATURES.map((feat, i) => {
              const rowIn = staggeredSpring(
                frame,
                vfps,
                i,
                TIMING.entrance + 46,
                TIMING.staggerItem,
                "GENTLE",
              );
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: base * 0.012,
                    opacity: rowIn,
                    transform: `translateX(${interpolate(
                      rowIn,
                      [0, 1],
                      [-base * 0.014, 0],
                    )}px)`,
                    fontFamily: "Inter, sans-serif",
                  }}
                >
                  <CheckIcon size={iconSize} progress={rowIn} />
                  <div
                    style={{
                      fontFamily: "Inter, sans-serif",
                      fontSize: featureSize,
                      fontWeight: 500,
                      color: COLORS.text,
                      letterSpacing: "-0.005em",
                      lineHeight: 1.2,
                    }}
                  >
                    {feat.label}
                  </div>
                </div>
              );
            })}
          </div>

          {/* CTA */}
          <div
            style={{
              marginTop: base * 0.024,
              opacity: ctaIn,
              transform: `translateY(${interpolate(
                ctaIn,
                [0, 1],
                [12, 0],
              )}px)`,
              fontFamily: "Inter, sans-serif",
            }}
          >
            <div
              style={{
                width: "100%",
                background: "transparent",
                border: `1.5px solid ${COLORS.orange}`,
                borderRadius: base * 0.01,
                padding: `${base * 0.016}px ${base * 0.02}px`,
                textAlign: "center",
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                fontSize: ctaSize,
                fontWeight: 700,
                color: COLORS.orange,
                letterSpacing: "-0.01em",
                boxSizing: "border-box",
              }}
            >
              Start for free
            </div>
          </div>

          {/* Footer */}
          <div
            style={{
              marginTop: base * 0.012,
              fontFamily: "Inter, sans-serif",
              fontSize: footerSize,
              fontWeight: 500,
              color: COLORS.textSubtle,
              letterSpacing: "-0.002em",
              textAlign: "center",
              opacity: footerIn,
              transform: `translateY(${interpolate(
                footerIn,
                [0, 1],
                [6, 0],
              )}px)`,
            }}
          >
            No credit card required.
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PricingCardScene;
